-- Purpose: plan_vs_actual.json rows (BUSINESS_PLAN_VS_ACTUAL; real plants, ZSPR/ZSPN; variance % recomputed, NULL when plan is 0).
-- Result rows: 5843
-- Data asset id: 6b05d54b5be48659f48aca5e (sync 9b99fd06-aae5-4182-9482-f05f2f11522a, r1-planvsactual-20261125-1420)
SELECT CALENDAR_MONTH AS MONTH, PLANT_ID, MATERIAL_GROUP, MATERIAL_TYPE, SHUTDOWN_DRIVEN, PLAN_VALUE_INR, ACTUAL_PO_VALUE_INR, ACTUAL_GR_VALUE_INR, VARIANCE_INR, CASE WHEN PLAN_VALUE_INR = 0 THEN NULL ELSE ROUND(VARIANCE_INR / PLAN_VALUE_INR * 100, 2) END AS VARIANCE_PCT FROM VEDANTA_POC.BUSINESS_PLAN_VS_ACTUAL WHERE PLANT_ID IN ('HZL_DEMO_01','HZL_DEMO_02','HZL_DEMO_03','HZL_DEMO_04','HZL_DEMO_05','HZL_DEMO_06') AND MATERIAL_TYPE IN ('ZSPR','ZSPN') ORDER BY CALENDAR_MONTH, PLANT_ID, MATERIAL_GROUP, MATERIAL_TYPE, SHUTDOWN_DRIVEN
